import java.util.*; import java.io.*; public class Main { static class Point { int r, c; Point(int r, int c) { this.r = r; this.c = c; } @Override public boolean equals(Object o) { Point p = (Point) o; return r == p.r && c == p.c; } @Override public int hashCode() { return Objects.hash(r, c); } } public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); StringTokenizer st = new StringTokenizer(br.readLine()); int T = Integer.parseInt(st.nextToken()); StringBuilder sb = new StringBuilder(); while (T-- > 0) { st = new StringTokenizer(br.readLine()); int N = Integer.parseInt(st.nextToken()); int M = Integer.parseInt(st.nextToken()); int K = Integer.parseInt(st.nextToken()); Set<Point> plants = new HashSet<>(K * 2); Point[] arr = new Point[K]; for (int i = 0; i < K; i++) { st = new StringTokenizer(br.readLine()); int r = Integer.parseInt(st.nextToken()); int c = Integer.parseInt(st.nextToken()); arr[i] = new Point(r, c); plants.add(arr[i]); } long perimeter = 0; int[] dr = {0, 0, 1, -1}; int[] dc = {1, -1, 0, 0}; for (Point p : arr) { int count = 0; for (int i = 0; i < 4; i++) { if (plants.contains(new Point(p.r + dr[i], p.c + dc[i]))) { count++; } } perimeter += (4 - count); } sb.append(perimeter).append("\n"); } System.out.print(sb); } }